import {
    Group,
    Mesh,
    PlaneGeometry,
    RingGeometry,
    MeshBasicNodeMaterial,
    MeshStandardNodeMaterial,
    Vector3
} from 'three/webgpu';
import {
    uv,
    vec2,
    vec3,
    color,
    mix,
    length,
    sub,
    add,
    div,
    mul,
    step,
    fract,
    max,
    clamp,
    pow,
    min,
    floor,
    asin,
    acos,
    sin,
    cos,
    atan2,
    normalize,
    dot,
    abs
} from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';
/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {Object} textContent
 * @property {string} textContent.headline
 * @property {string} textContent.body
 * @property {string} textContent.cta
 * @property {Array} cinematicPrimitives
 */
/**
 * @typedef {Object} NodeContext
 * @property {any} primitives
 * @property {any} textureLoader
 * @property {any} glbLoader
 * @property {any} fontAtlas
 */
/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three/webgpu').Object3D}
 */
export default function createNode(config, ctx) {
    const root = new Group();

    // placement
    const pos = config.position || { x: 0, y: 0, z: 0 };
    const rot = config.rotation || { x: 0, y: 0, z: 0 };
    const scl = config.scale || { x: 1, y: 1, z: 1 };
    root.position.set(pos.x, pos.y, pos.z);
    root.rotation.set(rot.x, rot.y, rot.z);
    root.scale.set(scl.x, scl.y, scl.z);

    // panel size
    const PANEL_W = 3.2;
    const PANEL_H = 2.2;

    // ----- Background with radial gradient, grid, border -----
    const bgGeom = new PlaneGeometry(PANEL_W, PANEL_H);
    const uvNode = uv();

    // radial gradient
    const centerUV = vec2(0.5, 0.5);
    const dist = length(sub(uvNode, centerUV));
    const maxDist = Math.sqrt(0.5 * 0.5 + 0.5 * 0.5);
    const tGrad = clamp(div(dist, maxDist), 0.0, 1.0);
    const gradColor = mix(color('#14141a'), color('#0b0b10'), tGrad);

    // grid (0.25 scene units pitch)
    const pitchU = 0.25 / PANEL_W;
    const pitchV = 0.25 / PANEL_H;
    const lineSize = 0.001;
    const gridU = step(fract(div(uvNode.x, pitchU)), lineSize);
    const gridV = step(fract(div(uvNode.y, pitchV)), lineSize);
    const gridMask = max(gridU, gridV);
    const gridColor = mul(color('#e8ecf2'), mul(gridMask, 0.06));

    // border (0.006 unit thickness)
    const borderU = 0.006 / PANEL_W;
    const borderV = 0.006 / PANEL_H;
    const leftMask = step(uvNode.x, borderU);
    const rightMask = step(1.0 - uvNode.x, borderU);
    const topMask = step(1.0 - uvNode.y, borderV);
    const bottomMask = step(uvNode.y, borderV);
    const borderMask = max(max(leftMask, rightMask), max(topMask, bottomMask));
    const borderColor = mul(color('#26262f'), borderMask);

    const finalColor = add(gradColor, add(gridColor, borderColor));

    const bgMaterial = new MeshBasicNodeMaterial({
        color: finalColor,
        transparent: true,
        opacity: 0
    });
    const bgMesh = new Mesh(bgGeom, bgMaterial);
    bgMesh.position.set(0, 0, 0);
    root.add(bgMesh);

    // ----- Ghost preview group -----
    const ghostGroup = new Group();

    const GHOST_OPACITY_MIN = 0.24;
    const GHOST_OPACITY_MAX = 0.34;

    // rectangle outline (wireframe)
    const rectW = 1.1;
    const rectH = 1.4;
    const rectGeom = new PlaneGeometry(rectW, rectH);
    const rectMat = new MeshBasicNodeMaterial({
        color: color('#e8ecf2'),
        transparent: true,
        opacity: 0.30,
        wireframe: true
    });
    const rectMesh = new Mesh(rectGeom, rectMat);
    rectMesh.position.set(-PANEL_W * 0.25, 0, 0.01);
    ghostGroup.add(rectMesh);

    // ghost dial (circle)
    const dialDiameter = 0.55;
    const dialRadius = dialDiameter / 2;
    const dialGeom = new RingGeometry(dialRadius * 0.95, dialRadius, 64);
    const dialMat = new MeshBasicNodeMaterial({
        color: color('#e8ecf2'),
        transparent: true,
        opacity: 0.30,
        side: 2
    });
    const dialMesh = new Mesh(dialGeom, dialMat);
    dialMesh.position.set(-PANEL_W * 0.25, 0, 0.02);
    ghostGroup.add(dialMesh);

    // ghost text bars
    const barW = 0.7 * rectW;
    const barH = 0.06;
    const barGeom = new PlaneGeometry(barW, barH);
    const barMat = new MeshBasicNodeMaterial({
        color: color('#e8ecf2'),
        transparent: true,
        opacity: 0.22
    });
    const bar1 = new Mesh(barGeom, barMat);
    const bar2 = new Mesh(barGeom, barMat);
    bar1.position.set(-PANEL_W * 0.25, -0.18, 0.02);
    bar2.position.set(-PANEL_W * 0.25, -0.30, 0.02);
    ghostGroup.add(bar1, bar2);

    root.add(ghostGroup);

    // breathing animation for ghost group
    const ghostState = { opacity: GHOST_OPACITY_MIN };
    const ghostTL = gsap.timeline({ repeat: -1, yoyo: true });
    ghostTL.to(ghostState, {
        opacity: GHOST_OPACITY_MAX,
        duration: 1.2,
        ease: 'cubic-bezier(0.445,0.05,0.55,0.95)',
        onUpdate: () => {
            ghostGroup.traverse((obj) => {
                if (obj.material && obj.material.opacity !== undefined) {
                    obj.material.opacity = ghostState.opacity;
                }
            });
        }
    });

    // ----- Text column -----
    const padding = 0.5; // 2 * base
    const columnX = -PANEL_W / 2 + padding + (PANEL_W - 2 * padding) / 2; // centered horizontally

    // Headline
    const headline = createText(
        {
            text: config.textContent?.headline ?? '',
            fontSize: 0.34,
            fontFamily: 'Lora',
            fontWeight: 600,
            color: '#e8ecf2',
            align: 'center',
            maxWidth: PANEL_W - 2 * padding
        },
        ctx
    );
    headline.position.set(columnX, PANEL_H / 2 - padding - 0.34 / 2, 0.03);
    root.add(headline);

    // Body
    const body = createText(
        {
            text: config.textContent?.body ?? '',
            fontSize: 0.13,
            fontFamily: 'JetBrains Mono',
            fontWeight: 400,
            color: '#e8ecf2',
            align: 'center',
            maxWidth: PANEL_W - 2 * padding,
            lineHeight: 1.5
        },
        ctx
    );
    const bodyY = headline.position.y - 0.34 / 2 - 0.13 * 1.5;
    body.position.set(columnX, bodyY, 0.03);
    root.add(body);

    // CTA button
    const CTA_W = 1.5;
    const CTA_H = 0.36;
    const ctaGeom = new PlaneGeometry(CTA_W, CTA_H);
    const ctaUV = uv();
    const ctaGrad = mix(color('#ff4450'), color('#c1121f'), ctaUV.y);
    const ctaMat = new MeshBasicNodeMaterial({
        color: ctaGrad,
        transparent: true,
        opacity: 1
    });
    const ctaMesh = new Mesh(ctaGeom, ctaMat);
    const ctaY = body.position.y - 0.13 - CTA_H / 2 - 0.1;
    ctaMesh.position.set(columnX, ctaY, 0.03);
    root.add(ctaMesh);

    // CTA label
    const ctaLabel = createText(
        {
            text: config.textContent?.cta ?? '',
            fontSize: 0.13,
            fontFamily: 'JetBrains Mono',
            fontWeight: 700,
            color: '#16161d',
            align: 'center',
            maxWidth: CTA_W
        },
        ctx
    );
    ctaLabel.position.set(0, 0, 0.01);
    ctaMesh.add(ctaLabel);

    // press interaction (scale down)
    const pressTimeline = gsap.timeline({ paused: true });
    pressTimeline.to(ctaMesh.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
    });
    const releaseTimeline = gsap.timeline({ paused: true });
    releaseTimeline.to(ctaMesh.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
    });
    ctaMesh.userData.handlers = {
        pointerdown: () => {
            pressTimeline.restart();
        },
        pointerup: () => {
            releaseTimeline.restart();
        },
        pointerleave: () => {
            releaseTimeline.restart();
        }
    };
    root.userData.handlers = {};

    // ----- Mount fade‑up animation -----
    const overall = { opacity: 0 };
    const mountTL = gsap.timeline();
    mountTL.to(overall, {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        onUpdate: () => {
            root.traverse((obj) => {
                if (obj.material && obj.material.transparent) {
                    obj.material.opacity = overall.opacity;
                }
            });
        }
    });
    mountTL.from(
        root.position,
        {
            y: root.position.y + 0.2,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        },
        0
    );

    // ----- Cleanup ----------
    root.userData.cleanup = () => {
        mountTL.kill();
        ghostTL.kill();
        pressTimeline.kill();
        releaseTimeline.kill();
        root.traverse((obj) => {
            if (obj.geometry) obj.geometry.dispose();
            if (obj.material) {
                if (Array.isArray(obj.material)) {
                    obj.material.forEach((m) => m.dispose());
                } else {
                    obj.material.dispose();
                }
            }
        });
    };

    // Apply cinematic primitives if any (none in this spec)
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach((prim) => {
            const fn = ctx.primitives?.[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        });
    }

    return root;
}
